import net.runelite.client.ui.components.PluginErrorPanel;

/**
 * Side panel listing every camera point, with controls to add new ones.
 */
public class CameraPointsPanel extends PluginPanel
{
	private final LocationCameraPointsPlugin plugin;
	private final JPanel listPanel = new JPanel(new GridBagLayout());
	private final PluginErrorPanel emptyPanel = new PluginErrorPanel();

	public CameraPointsPanel(LocationCameraPointsPlugin plugin)
	{
		this.plugin = plugin;

		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setBorder(new EmptyBorder(0, 0, 10, 0));

		JLabel title = new JLabel("Location Camera Points");
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());
		header.add(title, BorderLayout.NORTH);

		JButton addButton = new JButton("Add point at my location");
		addButton.setToolTipText("Create a point here using your current camera direction and zoom");
		addButton.addActionListener(e -> plugin.addPointAtPlayer());
		header.add(addButton, BorderLayout.CENTER);

		JLabel hint = new JLabel("<html>Tip: shift right-click a tile to add a point there.</html>");
		hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		hint.setFont(FontManager.getRunescapeSmallFont());
		header.add(hint, BorderLayout.SOUTH);

		emptyPanel.setContent("No camera points",
			"Stand somewhere, set up your camera, then click the button above.");

		add(header, BorderLayout.NORTH);
		add(listPanel, BorderLayout.CENTER);

		rebuild();
	}

	/**
	 * Recreates the list from the plugin's points. Must be called on the Swing thread.
	 */
	public void rebuild()
	{
		listPanel.removeAll();

		GridBagConstraints c = new GridBagConstraints();
		c.fill = GridBagConstraints.HORIZONTAL;
		c.weightx = 1;
		c.gridx = 0;
		c.gridy = 0;
		c.insets = new Insets(0, 0, 10, 0);

		List<CameraPoint> points = plugin.getPoints();
		if (points.isEmpty())
		{
			listPanel.add(emptyPanel, c);
		}

		for (int i = 0; i < points.size(); i++)
		{
			listPanel.add(new CameraPointPanel(plugin, points.get(i), i > 0, i < points.size() - 1), c);
			c.gridy++;
		}

		listPanel.revalidate();
		listPanel.repaint();
	}
}

package com.locationcamerapoints;

import static org.junit.Assert.assertEquals;
import com.google.gson.Gson;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class CameraPointTest
{
	private final CameraPoint point = new CameraPoint("Bank", 3200, 3200, 0, 2, CameraDirection.EAST, true, 600, true, true);

	@Test
	public void insideRadiusReturnsDistance()
	{
		assertEquals(0, point.distanceIfInside(new WorldPoint(3200, 3200, 0)));
		assertEquals(2, point.distanceIfInside(new WorldPoint(3202, 3198, 0)));
	}

	@Test
	public void outsideRadiusOrOtherPlaneIsMinusOne()
	{
		assertEquals(-1, point.distanceIfInside(new WorldPoint(3203, 3200, 0)));
		assertEquals(-1, point.distanceIfInside(new WorldPoint(3200, 3200, 1)));
	}

	@Test
	public void directionFromYawRoundsToNearestCardinal()
	{
		assertEquals(CameraDirection.SOUTH, CameraDirection.fromYaw(0));
		assertEquals(CameraDirection.SOUTH, CameraDirection.fromYaw(2000));
		assertEquals(CameraDirection.WEST, CameraDirection.fromYaw(600));
		assertEquals(CameraDirection.NORTH, CameraDirection.fromYaw(1024));
		assertEquals(CameraDirection.EAST, CameraDirection.fromYaw(1500));
	}

	@Test
	public void survivesJsonRoundTrip()
	{
		Gson gson = new Gson();
		assertEquals(point, gson.fromJson(gson.toJson(point), CameraPoint.class));
	}

	@Test
	public void missingDirectionDefaultsToKeep()
	{
		CameraPoint loaded = new Gson().fromJson("{\"x\":1,\"y\":2}", CameraPoint.class);
		assertEquals(CameraDirection.KEEP, loaded.getDirection());
	}
}

